def log_error(where, exc=None):
    try:
        base = os.path.join(os.environ.get("LOCALAPPDATA") or os.path.expanduser("~"), "Atelier PDM")
        os.makedirs(base, exist_ok=True)
        with open(os.path.join(base, "atelier_error.log"), "a", encoding="utf-8") as f:
            f.write(f"\n===== {time.strftime('%Y-%m-%d %H:%M:%S')} · {where} (2.8.1) =====\n")
            f.write(traceback.format_exc() if exc is not None else "")
    except Exception:                                           # noqa: BLE001
        pass


def best_size(px):
    return min(LOGO, key=lambda s: (abs(s - px), -s))


def logo_photo(widget, px):
    import tkinter as tk
    size = best_size(int(round(px)))
    root = widget.winfo_toplevel()
    key = (str(root), size)
    if key not in _IMG:
        _IMG[key] = tk.PhotoImage(master=root, data=LOGO[size])
    return _IMG[key]


def paint_logo(canvas, px, bg):
    try:
        img = logo_photo(canvas, px)
        size = img.width()
        canvas.delete("all")
        canvas.configure(bg=bg, width=size, height=size, highlightthickness=0, bd=0)
        canvas.create_image(size // 2, size // 2, image=img)
        canvas._atl_logo = img
        return True
    except Exception as e:                                      # noqa: BLE001
        log_error("logo", e)
        return False


def set_window_icon(root):
    """Window, Alt-Tab and taskbar icon from the built-in images (sharp at any scaling)."""
    try:
        import tkinter as tk
        imgs = [tk.PhotoImage(master=root, data=LOGO[s]) for s in (256, 64, 48, 32, 24, 16)]
        root.iconphoto(True, *imgs)
        root._atl_icons = imgs
    except Exception as e:                                      # noqa: BLE001
        log_error("window icon", e)


# =============================================================================
# Preview without a mesh
# =============================================================================
def render_placeholder(canvas, w, h, t, cam, title, hint):
    try:
        E.draw_backdrop(canvas, w, h, t)
        target = min(w * 0.42, (h - 70) * 0.72)
        size = max(s for s in LOGO if s <= max(48, target)) if any(s <= target for s in LOGO) else 48
        img = logo_photo(canvas, size)
        size = img.width()
        cy = max(size // 2 + 6, (h - 64) // 2)
        canvas.create_image(w // 2, cy, image=img)
        canvas._atl_logo = img
        canvas.create_text(w / 2, cy + size / 2 + 14, text=getattr(E, "APP_NAME", "Atelier PDM"), fill=t["fg"],
                           font=("Segoe UI Semibold", 12))
        canvas.create_text(w / 2, h - 30, text=title, fill=t.get("fg"), font=("Segoe UI Semibold", 9))
        canvas.create_text(w / 2, h - 14, text=hint, fill=t.get("muted_fg"), font=("Segoe UI", 8))
    except Exception as e:                                      # noqa: BLE001
        log_error("placeholder", e)
        ORIG["render_placeholder"](canvas, w, h, t, cam, title, hint)


ORIG = {}


# =============================================================================
# Cards: inner rows without their own outline
# =============================================================================
def _in_card(master):
    w = master
    while w is not None:
        try:
            if str(w.cget("style")) in ("Card.TFrame", "CardInner.TFrame"):
                return True
        except Exception:                                       # noqa: BLE001
            pass
        w = getattr(w, "master", None)
    return False


def _hook_frames():
    from tkinter import ttk
    if getattr(ttk.Frame, "_atl_inner", False):
        return
    orig = ttk.Frame.__init__

    def init(self, master=None, **kw):
        if kw.get("style") == "Card.TFrame" and master is not None and _in_card(master):
            kw["style"] = "CardInner.TFrame"
        orig(self, master, **kw)
    ttk.Frame.__init__ = init
    ttk.Frame._atl_inner = True


def _hook_style(m):
    orig = getattr(m, "style_ttk", None)
    if orig is None or getattr(orig, "_atl_polish", False):
        return

    def style_ttk(root, s, t, S):
        res = orig(root, s, t, S)
        try:
            s.configure("CardInner.TFrame", background=t["panel_bg"], borderwidth=0, relief="flat")
        except Exception:                                       # noqa: BLE001
            pass
        return res
    style_ttk._atl_polish = True
    m.style_ttk = style_ttk


# =============================================================================
# Standard Parts Library
# =============================================================================
def _rename_library(m):
    old = getattr(m, "STANDARD_LIB_DIR", None)
    if not old:
        return
    new = os.path.join(m.VAULT_DIR, LIB_NEW)
    try:
        if os.path.isdir(old) and not os.path.exists(new) and os.path.basename(old) == LIB_OLD:
            busy = False
            try:
                with m.db() as c:
                    busy = bool(c.execute("SELECT COUNT(*) FROM files WHERE is_library=1 AND locked_by IS NOT NULL "
                                          "AND locked_by<>''").fetchone()[0])
            except Exception:                                   # noqa: BLE001
                busy = False
            if not busy:
                os.rename(old, new)
                try:
                    with m.db() as c:
                        c.execute("UPDATE files SET folder_path=REPLACE(folder_path, ?, ?) WHERE folder_path LIKE ?",
                                  (LIB_OLD, LIB_NEW, LIB_OLD + "%"))
                    m.log_audit("[vault]", "Folder Renamed", "", f"{LIB_OLD} -> {LIB_NEW}")
                except Exception:                               # noqa: BLE001
                    pass
    except OSError as e:
        log_error("rename Standard Library (will use the old name for now)", e)
    if os.path.isdir(new) or not os.path.isdir(old):
        m.STANDARD_LIB_DIR = new
    try:
        m.PROTECTED_FOLDERS.add(LIB_NEW.lower())
    except AttributeError:
        pass


# =============================================================================
# Opening a CAD file also opens its panel
# =============================================================================
def panel_running(app_key):
    port = PANEL_PORTS.get(app_key)
    if not port:
        return True
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        s.bind(("127.0.0.1", port))
        return False
    except OSError:
        return True
    finally:
        s.close()


def launcher_command(*args):
    if getattr(sys, "frozen", False):
        return [sys.executable, *args]
    here = os.path.dirname(os.path.abspath(__file__))
    script = os.path.join(here, "atelier_launcher.py")
    if not os.path.isfile(script):
        return None
    exe = sys.executable
    if WIN:
        pw = os.path.join(os.path.dirname(exe), "pythonw.exe")
        exe = pw if os.path.exists(pw) else exe
    return [exe, script, *args]


def start_panel(app_key):
    if not WIN or app_key not in PANEL_PORTS or panel_running(app_key):
        return False
    try:
        if not (E.load_settings() or {}).get("open_panel_with_cad", True):
            return False
    except Exception:                                           # noqa: BLE001
        pass
    cmd = launcher_command("--panel", app_key, "--launch")
    if not cmd:
        return False
    env = dict(os.environ, ATELIER_ATTACH="1")
    try:
        subprocess.Popen(cmd, env=env, close_fds=True)
        return True
    except OSError as e:
        log_error("start panel", e)
        return False


def _hook_open(m):
    orig = getattr(m, "open_in_cad", None)
    if orig is None or getattr(orig, "_atl_polish", False):
        return

    def open_in_cad(filename, *a, **k):
        res = orig(filename, *a, **k)
        try:
            if res and res[0] != "error":
                start_panel(m.cad_app_of(filename))
        except Exception as e:                                  # noqa: BLE001
            log_error("open panel with CAD", e)
        return res
    open_in_cad._atl_polish = True
    m.open_in_cad = open_in_cad


def _hook_launcher():
    """Launched from Atelier with ATELIER_ATTACH set: the CAD program is already starting, so wait for it
    instead of starting a second copy."""
    L = sys.modules.get("__main__")
    orig = getattr(L, "prepare_cad", None)
    if orig is None or getattr(orig, "_atl_polish", False):
        return

    def prepare_cad(engine, panel, key, sleep=time.sleep):
        if not os.environ.get("ATELIER_ATTACH"):
            return orig(engine, panel, key, sleep)
        os.environ.pop("ATELIER_ATTACH", None)
        apps, find = getattr(panel, "APPS", None), getattr(panel, "find_window", None)
        if not apps or key not in apps or find is None:
            return False
        names = {n.lower() for n in apps[key].exe_names}
        L.wait_for_window(find, names, timeout=60, sleep=sleep)
        return True
    prepare_cad._atl_polish = True
    L.prepare_cad = prepare_cad


# =============================================================================
# Panels: hidden until docked
# =============================================================================
def patch_panel(mod):
    cls = getattr(mod, "Panel", None)
    if cls is None or getattr(cls, "_atl_polish", False):
        return
    cls._atl_polish = True
    o_place = getattr(cls, "_place_initial", None)
    o_apply = getattr(cls, "_apply_geometry", None)
    if o_place is None or o_apply is None:
        return

    def reveal(self):
        if not getattr(self, "_atl_hidden", False):
            return
        self._atl_hidden = False
        try:
            del self.root.deiconify
        except AttributeError:
            pass
        try:
            self.root.deiconify()
        except Exception:                                       # noqa: BLE001
            pass

    def _place_initial(self):
        set_window_icon(self.root)
        floating = not getattr(mod, "WIN", False) or self.mode_var.get() == "float"
        if floating:
            return o_place(self)
        self._atl_hidden = True
        self.root.withdraw()
        self.root.deiconify = lambda *a: None                   # stays hidden until it has docked
        o_place(self)
        self.root.after(15000, lambda: reveal(self))            # CAD program never appeared: show it anyway

    def _apply_geometry(self, *a, **k):
        res = o_apply(self, *a, **k)
        if getattr(self, "_atl_hidden", False) and self._decorated is False and self._last_geom:
            reveal(self)
        return res
    cls._place_initial = _place_initial
    cls._apply_geometry = _apply_geometry
    o_logo = getattr(cls, "_draw_logo", None)
    if o_logo:
        def _draw_logo(self):
            if not paint_logo(self.logo, self.S(22), self.t["header_bg"]):
                o_logo(self)
        cls._draw_logo = _draw_logo


class _Wrap(importlib.abc.Loader):
    def __init__(self, inner):
        self.inner = inner

    def create_module(self, spec):
        return self.inner.create_module(spec) if hasattr(self.inner, "create_module") else None

    def exec_module(self, module):
        self.inner.exec_module(module)
        try:
            patch_panel(module)
        except Exception as e:                                  # noqa: BLE001
            log_error("panel patch", e)


class _Finder(importlib.abc.MetaPathFinder):
    def find_spec(self, name, path, target=None):
        if name != "atelier_panel":
            return None
        try:
            sys.meta_path.remove(self)
        except ValueError:
            pass
        spec = importlib.util.find_spec(name)                   # lets any other patch wrap it too
        if spec is None or spec.loader is None:
            return None
        spec.loader = _Wrap(spec.loader)
        return spec


# =============================================================================
# Main window
# =============================================================================
def _hook_app(m):
    cls = getattr(m, "AtelierApp", None)
    if cls is None or getattr(cls, "_atl_polish", False):
        return
    cls._atl_polish = True
    o_logo = cls.draw_logo

    def draw_logo(self):
        if not paint_logo(self.logo, self.S(30), self.t["header_bg"]):
            o_logo(self)
    cls.draw_logo = draw_logo

    o_build = cls.build_ui

    def build_ui(self, *a, **k):
        res = o_build(self, *a, **k)
        set_window_icon(self.root)
        try:
            for w in self.logo.master.winfo_children():
                for lab in w.winfo_children() if hasattr(w, "winfo_children") else []:
                    if str(lab.cget("text")).startswith("CAD vault"):
                        lab.configure(text=f"CAD vault & part numbering  ·  v{VERSION}")
        except Exception:                                       # noqa: BLE001
            pass
        try:
            m_ = self.folders_menu
            for i in range((m_.index("end") or 0) + 1):
                if m_.type(i) == "command" and "Standard Library" in str(m_.entrycget(i, "label")):
                    m_.entryconfigure(i, label=LIB_NEW, command=lambda: self.open_folder(m.STANDARD_LIB_DIR))
        except Exception:                                       # noqa: BLE001
            pass
        return res
    cls.build_ui = build_ui


def install(module):
    global E
    E = module
    if getattr(module, "_polish_installed", False):
        return
    module._polish_installed = True
    for name in ("render_placeholder",):
        if hasattr(module, name):
            ORIG[name] = getattr(module, name)
            setattr(module, name, globals()[name])
    for step in (_hook_frames, lambda: _hook_style(module), lambda: _rename_library(module),
                 lambda: _hook_open(module), _hook_launcher, lambda: _hook_app(module)):
        try:
            step()
        except Exception as e:                                  # noqa: BLE001
            log_error("install step", e)
    if "atelier_panel" in sys.modules:
        patch_panel(sys.modules["atelier_panel"])
    else:
        sys.meta_path.insert(0, _Finder())
